function LogoItem({ partner }) {
  return (
    <a
      id={`partner-${partner.id}`}
      href={partner.url}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={partner.label}
      title={partner.label}
      className="group relative inline-flex items-center justify-center w-[200px] h-[90px] transition-all duration-300 hover:-translate-y-1"
    >
      {/* SVG/Img Wrapper with custom tight constraints for a unified same-size look */}
      <div className="h-12 w-44 max-w-full flex items-center justify-center text-neutral-400 group-hover:text-white transition-colors duration-300">
        {partner.isImg ? (
          <img 
            src={partner.imgSrc} 
            alt={partner.label} 
            className="h-14 w-auto object-contain transition-opacity duration-300 opacity-80 group-hover:opacity-100" 
          />
        ) : (
          partner.svg
        )}
      </div>
    </a>
  );
}

export default function PartnerLogos({ lang = "tr" }) {
  const heading = lang === "en" ? "Partners & References" : "Ortaklar & Referanslar";
  const sub = lang === "en"
    ? "Organizations defining the frontier of science and exploration"
    : "Bilim ve keşfin sınırlarını belirleyen kuruluşlar";

  return (
    <section className="glass-nav transition-theme" style={{ paddingTop: "64px", paddingBottom: "64px", borderTop: "1px solid var(--border-color)" }}>
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        {/* Heading */}
        <div className="text-center mb-10">
          <p className="font-mono text-[10px] uppercase tracking-widest mb-2" style={{ color: "var(--foreground-muted)" }}>
            {heading}
          </p>
          <p className="text-sm" style={{ color: "var(--foreground-subtle)" }}>{sub}</p>
        </div>

        {/* Logo grid - unified flat flexbox layout with same-size items */}
        <div className="flex flex-wrap items-center justify-center gap-5">
          {PARTNERS.map((p) => (
            <LogoItem key={p.id} partner={p} />
          ))}
        </div>
      </div>
    </section>
  );
}
